#!/usr/bin/env node
// Bundles src/metro/checkout/bundleEntry.ts — which re-exports both serverQuote.ts (create-
// metro-checkout's pricing/validation logic) and verifyLogic.ts (verify-metro-payment's
// decision logic), plus their transitive src/metro/** imports — into a single Deno-importable
// ESM file at supabase/functions/_shared/metro-checkout.bundle.js.
//
// Why: create-metro-checkout needs the exact same price-quoting logic the client uses
// (src/metro/lib/pricing.ts, src/metro/lib/dates.ts, src/metro/config/**) so the server can
// re-validate a client-submitted total instead of trusting it, and verify-metro-payment needs
// the same request/session validation, status mapping, and response-shaping logic. Deno can't
// import `@/`-aliased TS straight out of src/ in a deployable way, so — same approach as
// scripts/metro/export-price-book.mjs (esbuild is already a transitive Vite dependency in
// node_modules; no new dep added) — we bundle it ahead of time and check the output in.
//
// Unlike export-price-book.mjs (which bundles to a throwaway tmp file, imports it, and writes
// a derived JSON artifact), this script writes the bundle itself directly to its deployed
// location: the edge function imports supabase/functions/_shared/metro-checkout.bundle.js at
// runtime, so the bundle IS the artifact, not an intermediate.
//
// platform: 'neutral' (not 'node') — this source has zero Node-specific APIs (no fs/process/
// require), and 'neutral' avoids esbuild injecting any Node or browser shims that could behave
// differently under Deno.
//
// Run manually with `node scripts/metro/export-metro-checkout-bundle.mjs` any time
// src/metro/checkout/serverQuote.ts or anything it imports changes, and before
// `supabase functions deploy create-metro-checkout`. A vitest parity test
// (src/metro/checkout/bundleParity.test.ts) fails loudly with a reminder to re-run this
// script if the checked-in bundle drifts from source.
//
// ALSO generates supabase/functions/_shared/metro-checkout.bundle.d.ts (G2,
// docs/metro/research/metro-checkout-rereview.md): esbuild erases every `interface`/`type` from
// the .js bundle above, so a plain `import { type X } from "./metro-checkout.bundle.js"` in a
// consumer (_shared/metro-conversion-runner.ts) has nothing to resolve `X` against under a real
// type-checker (`deno check`/`tsc`) — silent `any`/error today, since nothing currently runs one
// over supabase/functions/**. Fixed via option (a) from the re-review: run the REAL TypeScript
// compiler's `--emitDeclarationOnly` over the same bundleEntry.ts dependency graph (so the types
// are tsc-verified, not hand-duplicated/copy-pasted and liable to drift), then roll the handful
// of names actually type-imported by consumers today into one flat .d.ts — see
// `emitDeclarations()` below for exactly which names and why (contract.ts/emailTemplates.ts are
// self-contained so are included whole; verifyLogic.ts/conversion.ts also declare things that
// reach the generated Supabase `Database` type, which nothing here actually needs, so those two
// are cherry-picked down to just the interfaces consumers import). The consumer then points at it
// via a `// @deno-types="./metro-checkout.bundle.d.ts"` comment directly above its import of the
// .js bundle — the Deno-standard way to attach a hand/generated declaration file to a plain .js
// import. `src/metro/checkout/bundleDeclarations.test.ts` fails loudly with a reminder to re-run
// this script if the checked-in .d.ts drifts from source (same pattern as bundleParity.test.ts).

import { build } from 'esbuild';
import ts from 'typescript';
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(__dirname, '..', '..');

const entry = path.join(repoRoot, 'src', 'metro', 'checkout', 'bundleEntry.ts');
const outDir = path.join(repoRoot, 'supabase', 'functions', '_shared');
const outFile = path.join(outDir, 'metro-checkout.bundle.js');
const dtsOutFile = path.join(outDir, 'metro-checkout.bundle.d.ts');

const banner = `// AUTO-GENERATED by scripts/metro/export-metro-checkout-bundle.mjs — DO NOT EDIT BY HAND.
// Source: src/metro/checkout/bundleEntry.ts (re-exports serverQuote.ts + verifyLogic.ts,
// + their transitive src/metro/** imports)
// Regenerate: node scripts/metro/export-metro-checkout-bundle.mjs
// Generated: ${new Date().toISOString()}
`;

async function main() {
  mkdirSync(outDir, { recursive: true });

  await build({
    entryPoints: [entry],
    outfile: outFile,
    bundle: true,
    platform: 'neutral',
    format: 'esm',
    target: 'es2022',
    logLevel: 'warning',
    banner: { js: banner },
  });

  console.log(`Wrote metro checkout bundle -> ${path.relative(repoRoot, outFile)}`);

  emitDeclarations();
}

// Whole files to inline verbatim into the .d.ts — only safe for files with zero imports (i.e.
// nothing that would need resolving once flattened into one file). Verified by direct read of
// their tsc-emitted output: both are entirely self-contained (contract.ts has no imports at all;
// emailTemplates.ts only uses primitive/built-in types).
const DTS_WHOLE_FILE_INCLUDES = ['metro/checkout/contract.ts', 'metro/checkout/emailTemplates.ts'];

// Specific interfaces to extract (by name, via a real AST lookup — not line/offset-based, so this
// stays correct even as the surrounding file changes) out of files that are NOT safe to inline
// whole, because most of their other declarations reach the generated Supabase `Database` type
// (huge) via `MetroOrderRow`. Extend this map (and the type-only import list in
// _shared/metro-conversion-runner.ts) if a consumer ever needs another type-only name from
// verifyLogic.ts/conversion.ts.
const DTS_CHERRY_PICKS = {
  'metro/checkout/verifyLogic.ts': ['MinimalStripeSession'],
  'metro/checkout/conversion.ts': ['ParsedMetroCheckout'],
};

function emitDeclarations() {
  const tmpDir = mkdtempSync(path.join(os.tmpdir(), 'mgg-metro-dts-'));
  try {
    const srcDir = path.join(repoRoot, 'src');
    const compilerOptions = {
      target: ts.ScriptTarget.ES2020,
      module: ts.ModuleKind.ESNext,
      moduleResolution: ts.ModuleResolutionKind.Bundler,
      declaration: true,
      emitDeclarationOnly: true,
      skipLibCheck: true,
      strict: false,
      noImplicitAny: false,
      outDir: tmpDir,
      rootDir: srcDir,
    };

    const program = ts.createProgram([entry], compilerOptions);
    const emitResult = program.emit();
    const diagnostics = [...ts.getPreEmitDiagnostics(program), ...emitResult.diagnostics];
    if (diagnostics.length > 0) {
      const formatted = ts.formatDiagnosticsWithColorAndContext(diagnostics, {
        getCurrentDirectory: () => repoRoot,
        getCanonicalFileName: f => f,
        getNewLine: () => ts.sys.newLine,
      });
      throw new Error(
        `TypeScript declaration emit for metro-checkout.bundle.d.ts reported diagnostics (fix the source, or this .d.ts would silently be wrong):\n${formatted}`,
      );
    }

    const readEmittedDts = relSrcPath => {
      const dtsPath = path.join(tmpDir, relSrcPath.replace(/\.ts$/, '.d.ts'));
      return readFileSync(dtsPath, 'utf8');
    };

    const sections = [];

    for (const rel of DTS_WHOLE_FILE_INCLUDES) {
      sections.push(`// ─── from src/${rel} (included in full — self-contained) ───\n${readEmittedDts(rel).trim()}`);
    }

    for (const [rel, names] of Object.entries(DTS_CHERRY_PICKS)) {
      const text = readEmittedDts(rel);
      const sourceFile = ts.createSourceFile(rel, text, ts.ScriptTarget.Latest, true);
      for (const name of names) {
        const node = sourceFile.statements.find(s => ts.isInterfaceDeclaration(s) && s.name.text === name);
        if (!node) {
          throw new Error(`Could not find exported interface '${name}' in tsc-emitted declarations for src/${rel}.`);
        }
        const slice = text.slice(node.getFullStart(), node.getEnd()).trim();
        sections.push(`// ─── ${name}, from src/${rel} (cherry-picked) ───\n${slice}`);
      }
    }

    const dtsBanner = `// AUTO-GENERATED by scripts/metro/export-metro-checkout-bundle.mjs — DO NOT EDIT BY HAND.
// Type declarations for metro-checkout.bundle.js (G2, docs/metro/research/metro-checkout-rereview.md).
// Real tsc --emitDeclarationOnly output for src/metro/checkout/bundleEntry.ts's dependency graph
// (tsc-verified, not hand-duplicated), scoped to only the names _shared/metro-conversion-runner.ts
// (and any other edge function) actually type-imports from the bundle today. See
// scripts/metro/export-metro-checkout-bundle.mjs's DTS_WHOLE_FILE_INCLUDES/DTS_CHERRY_PICKS for
// exactly what's included and why.
// Regenerate: node scripts/metro/export-metro-checkout-bundle.mjs
// Generated: ${new Date().toISOString()}
`;

    writeFileSync(dtsOutFile, `${dtsBanner}\n${sections.join('\n\n')}\n`);
    console.log(`Wrote metro checkout bundle declarations -> ${path.relative(repoRoot, dtsOutFile)}`);
  } finally {
    rmSync(tmpDir, { recursive: true, force: true });
  }
}

main().catch(err => {
  console.error('export-metro-checkout-bundle failed:', err);
  process.exitCode = 1;
});
